   'CASCADE-SHADOW-1 (qnfo-ai 5.48.0): the trigger is declared in wrangler.toml and installed by the canonical deploy; fm-cascade-shadow-silent reads a finished cascade-shadow-run inside 26 hours (or the switch set to off); a fault names itself in a run row with status error',
   'd1-query over cloud_ops_events kind cascade-shadow-run: a row with status ok in the last 26 hours, or ops_config cascade_shadow off',
   'fm-cascade-shadow-silent', '2026-11-05', NULL,
   'the cron trigger was dropped from a deploy, the binding failed on every call three times in 22 hours, or the gate or the switch read wrongly',
   'no cascade-shadow-run row with status ok for 26 hours while the switch is on',
   'no stage is moved by the shadow, so only the evidence goes stale; spend is not at risk');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, verify_probe, verify_transport, max_attempts, expected_cadence_h, status, precondition, action, escalate_to) VALUES
  ('fm-cascade-shadow-silent', NULL,
   'SELECT ''1'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM cloud_ops_events WHERE kind = ''cascade-shadow-run'' AND status = ''ok'' AND ts > strftime(''%Y-%m-%dT%H:%M:%fZ'', ''now'', ''-26 hours'')) OR EXISTS (SELECT 1 FROM ops_config WHERE key = ''cascade_shadow'' AND lower(trim(value)) IN (''off'', ''0'', ''false'', ''no'')) THEN ''1'' ELSE ''0'' END AS observed',
   'd1-query', 3, 1, 'active', 'RM-BS-QUNIVERSE-SMALL-1 slice 1 (PR 7689)', 'failure-mode detector', 'qnfo-code-orchestrator');

